macro.command:
// 奧術回想 - 物品宏形式
// 點擊角色卡內的專屬能力或物品時使用
// 兼容 FoundryVTT DND5e

if (!actor) return ui.notifications.warn("沒有找到角色！");
if (!item) return ui.notifications.warn("沒有找到奧術回想ArcaneRecovery物品！");

// 檢查使用次數
const uses = item.system.uses?.value ?? 0;
const usesMax = item.system.uses?.max ?? 1;
if (uses < 1) {
  return ui.notifications.warn("奧術回想已沒有剩餘使用次數！");
}

// 先消耗一次
await item.update({"system.uses.value": uses - 1});

// 以下爲奧術回想的主要功能
const wizardLevel = actor.items.find(i => i.type==="class" && i.name==="法師wizard")?.system.levels;
if (!wizardLevel) return ui.notifications.warn("找不到你的法師等級！");

const maxPoints = Math.ceil(wizardLevel / 2);
const slotLevels = [1,2,3,4,5];

let maxRecoverable = {};
slotLevels.forEach(lvl => {
  const total = getProperty(actor.system, `spells.spell${lvl}.max`) ?? 0;
  const used = total - (getProperty(actor.system, `spells.spell${lvl}.value`) ?? 0);
  maxRecoverable[lvl] = Math.max(0, used);
});

let content = `<form><div>你最多可恢復一共 <b>${maxPoints}</b> 環法術位（注意奧術回想所恢復的單個環位最高不能超過5環）：</div>`;
slotLevels.forEach(lvl => {
  content += `
    <div class="form-group">
      <label>${lvl}環（已消耗: ${maxRecoverable[lvl]}）:</label>
      <input type="number" min="0" max="${maxRecoverable[lvl]}" value="0" id="arcane-lvl${lvl}">
    </div>
  `;
});
content += `</form>`;

new Dialog({
  title: "奧術回想 - 恢復法術位",
  content,
  buttons: {
    confirm: {
      label: "恢復",
      callback: async (html) => {
        let totalSpent = 0;
        let restoreData = {};
slotLevels.forEach(lvl => {
          let n = Number(html.find(`#arcane-lvl${lvl}`).val()) || 0;
          n = Math.min(n, maxRecoverable[lvl]);
          totalSpent += lvl * n;
          restoreData[lvl] = n;
});
        if (totalSpent === 0) {
          return ui.notifications.warn("你沒有選擇恢復任何法術位。");
}
        if (totalSpent > maxPoints) {
          return ui.notifications.warn(`你選擇的法術位總環數爲${totalSpent}，已超過最大可恢復點數${maxPoints}！`);
}

        // 更新法術位
        let updates = {};
slotLevels.forEach(lvl => {
          if (restoreData[lvl] > 0) {
            const path = `system.spells.spell${lvl}.value`;
            const cur = getProperty(actor, path) ?? 0;
            updates[path] = Math.min(
              cur + restoreData[lvl],
              getProperty(actor.system, `spells.spell${lvl}.max`) ?? 0
            );
}
});

        await actor.update(updates);

        // 聊天提示
        let txt = `${actor.name} 用奧術回想恢復了：`;
        txt += slotLevels.filter(lvl => restoreData[lvl]>0).map(lvl=>`${restoreData[lvl]}個${lvl}環`).join("，");
        txt += `（共消耗點數${totalSpent}，最大可用${maxPoints}）`;
        ChatMessage.create({
          speaker: ChatMessage.getSpeaker({actor: actor}),
          content: txt
});
}
    },
    cancel: { label: "取消" }
}
}).render(true);
